const rows = $input.all();

// Rango del informe: debe coincidir con el de Validar_Completitud
const FECHA_INICIO = new Date("2026-04-16T00:00:00");
const FECHA_FIN = new Date("2026-05-13T23:59:59");

const meses = {
  enero: 0,
  febrero: 1,
  marzo: 2,
  abril: 3,
  mayo: 4,
  junio: 5,
  julio: 6,
  agosto: 7,
  septiembre: 8,
  octubre: 9,
  noviembre: 10,
  diciembre: 11,
};

function parseFecha(fechaTexto) {
  if (!fechaTexto) return null;

  const partes = String(fechaTexto).toLowerCase().split(",");
  if (partes.length < 3) return null;

  const mesDia = partes[1].trim().split(" ");
  const mes = mesDia[0];
  const dia = Number(mesDia[1]);
  const anio = Number(partes[2].trim());

  if (!(mes in meses) || !dia || !anio) return null;

  return new Date(anio, meses[mes], dia);
}

// Fecha ISO en hora local (toISOString usa UTC y puede correr un día)
function formatDateISO(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

const cleaned = [];

for (const row of rows) {
  const data = row.json;

  const fecha = data["FECHA"];
  const actividad = data["Actividad base"];
  const evidencia = data["EVIDENCIA"];
  const mes_del_informe = data["MES DEL INFORME"];

  // Solo descarta filas completamente vacías
  if (!fecha && !actividad && !evidencia) continue;

  const alertas = [];

  const fechaObj = parseFecha(fecha);

  // Si no hay fecha válida, NO se elimina la actividad.
  // Solo se agrega alerta.
  if (!fechaObj) {
    alertas.push("SIN_FECHA");
  }

  // Solo filtra por rango cuando sí existe fecha válida
  if (fechaObj && (fechaObj < FECHA_INICIO || fechaObj > FECHA_FIN)) {
    continue;
  }

  const evidencias = evidencia
    ? String(evidencia).split("\n").map(e => e.trim()).filter(Boolean)
    : [];

  if (evidencias.length === 0) {
    alertas.push("SIN_EVIDENCIA");
  }

  for (const ev of evidencias) {
    if (!ev.includes(".")) {
      alertas.push("EVIDENCIA_SIN_EXTENSION");
    }
  }

  cleaned.push({
    json: {
      fecha_original: fecha || "",
      fecha_iso: fechaObj ? formatDateISO(fechaObj) : "",
      mes_del_informe,
      actividad_base: actividad,
      evidencias_originales: evidencias,
      alertas
    }
  });
}

return cleaned;

const items = $input.all();

return items.map((item, index) => {
  try {
    // 1. Extraer respuesta de la IA
    const rawText = item.json.choices?.[0]?.message?.content;
    if (!rawText) throw new Error("Respuesta de IA vacía");

    // 2. Limpiar y parsear JSON de la IA
    const parsedIA = JSON.parse(
      rawText
        .replace(/```json/g, "")
        .replace(/```/g, "")
        .trim()
    );

    // 3. Recuperar datos originales desde Validar_Completitud
    const originalRef = $item(index).$node["Validar_Completitud"].json;

    // 4. Normalizar evidencias
    const evidenciasOriginales = Array.isArray(originalRef.evidencias_originales)
      ? originalRef.evidencias_originales.join(", ")
      : "";

    // 5. Normalizar alertas
    const alertas = Array.isArray(originalRef.alertas)
      ? originalRef.alertas
      : [];

    // 6. Construir observaciones finales sin duplicar explicación
    const observaciones = [];

    if (parsedIA.observaciones) {
      observaciones.push(parsedIA.observaciones);
    }

    if (alertas.length > 0) {
      const observacionesTexto = observaciones.join(" ").toUpperCase();

      for (const alerta of alertas) {
        if (!observacionesTexto.includes(alerta.toUpperCase())) {
          observaciones.push(`Alerta: ${alerta}`);
        }
      }
    }

    return {
      json: {
        fecha: originalRef.fecha_iso || "",
        fecha_original: originalRef.fecha_original || originalRef.fecha_iso || "",
        mes_del_informe: originalRef.mes_del_informe || "MAYO",

        obligacion: parsedIA.obligacion || "",
        descripcion_obligacion: parsedIA.descripcion_obligacion || "",

        actividad_original: originalRef.actividad_base || "",
        actividad_corregida: parsedIA.actividad_corregida || "",
        titulo_actividad: parsedIA.titulo_actividad || "",

        evidencias: parsedIA.evidencias || evidenciasOriginales,

        estado_revision: "PENDIENTE",
        explicacion_clasificacion: parsedIA.explicacion_clasificacion || "",
        observaciones: observaciones.join(" | "),

        fuente: "Actividades_2026",
        alertas: alertas
      }
    };

  } catch (error) {
    return {
      json: {
        error: "Error en sincronización",
        detalle: error.message,
        indice: index,
        estado_revision: "ERROR"
      }
    };
  }
});

// 1. Rango del informe de mayo: debe coincidir con el de Normalizar_Datos
// (hora local; new Date('AAAA-MM-DD') se interpreta en UTC)
const fechaInicio = new Date('2026-04-16T00:00:00');
const fechaFin = new Date('2026-05-13T00:00:00');

// 2. Configuración del informe
const MES_DEL_INFORME = "MAYO";

// 3. Lista de festivos en Colombia para este periodo
const festivos = ['2026-05-01'];

const items = $input.all();
const actividadesExistentes = items
  .map(item => item.json.fecha_iso)
  .filter(Boolean);

const resultados = [...items];

// 4. Función para formatear fecha ISO sin desfase
function formatDateISO(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

// 5. Recorrer los días del periodo
let fechaActual = new Date(fechaInicio);

while (fechaActual <= fechaFin) {
  const isoDate = formatDateISO(fechaActual);
  const diaSemana = fechaActual.getDay(); // 0: domingo, 6: sábado

  const esHabil = diaSemana !== 0 && diaSemana !== 6;
  const esFestivo = festivos.includes(isoDate);

  if (esHabil && !esFestivo) {
    if (!actividadesExistentes.includes(isoDate)) {
      resultados.push({
        json: {
          fecha_original: isoDate,
          fecha_iso: isoDate,
          mes_del_informe: MES_DEL_INFORME,
          actividad_base: "Seguimiento daily (DAILY)",
          evidencias_originales: [],
          alertas: [
            "DIA_RELLENADO_AUTOMATICAMENTE",
            "REVISAR_ACTIVIDAD_MANUAL"
          ],
          es_automatico: true
        }
      });
    }
  }

  fechaActual.setDate(fechaActual.getDate() + 1);
}

// 6. Ordenar por fecha
return resultados.sort((a, b) => {
  const fechaA = a.json.fecha_iso || "";
  const fechaB = b.json.fecha_iso || "";
  return new Date(fechaA) - new Date(fechaB);
});
